def main():
    parser = argparse.ArgumentParser(
        description="Create absent corpus files from pinned Memos source. Preserve existing cases and reviews.",
        formatter_class=lambda prog: argparse.HelpFormatter(prog, width=max(40, shutil.get_terminal_size().columns), max_help_position=18),
    )
    parser.add_argument("--cache", type=Path, required=True, metavar="EXTERNAL_MIRROR", help="Path to the external bare Memos repository.")
    args = parser.parse_args()
    cache = args.cache
    if not cache.is_dir():
        parser.error("The external mirror is absent. Set --cache to an existing bare Memos repository.")

    def git(*argv, check=True):
        return subprocess.run(["git", f"--git-dir={cache}", *argv], capture_output=True, check=check)

    def blob(revision, path):
        return git("show", f"{revision}:{path}").stdout

    def sha(data):
        return hashlib.sha256(data).hexdigest()

    def write(path, value):
        data = (json.dumps(value, sort_keys=True, ensure_ascii=False, indent=2) + "\n").encode()
        path.write_bytes(data)
        return sha(data)

    template = json.loads((ROOT / "memos/memos-log-level.json").read_text())
    inventory = []
    created = 0
    for seed in sorted((ROOT / "memos").glob("*.json")):
        case = load_case(seed)
        inventory.append(dict(id=case["id"], group=case["group"], types=case["types"], dataset=case["dataset"], manifest=str(seed.relative_to(ROOT)), origin="development_seed"))
    for number, definition in enumerate(CASES, 801):
        name, commit = definition["id"], definition["commit"]
        parent = git("rev-parse", f"{commit}^").stdout.decode().strip()
        tree = git("rev-parse", f"{commit}^{{tree}}").stdout.decode().strip()
        git("merge-base", "--is-ancestor", commit, "main")
        changed = git("diff", "--name-only", parent, commit).stdout.decode().splitlines()
        facts = copy.deepcopy(definition["facts"])
        for index, item in enumerate(facts, 1):
            item["id"] = f"behavior-{index}"
            paths = item.pop("paths")
            item["sources"] = []
            for path in paths:
                blob(commit, path)
                item["sources"].append(dict(revision=commit, path=path, symbol="The cited source file", url=f"https://github.com/usememos/memos/blob/{commit}/{path}"))
        manifest = ROOT / "memos/corpus" / f"{name}.json"
        inventory.append(dict(id=name, group=name, types=[definition["type"]], dataset=definition["dataset"], manifest=str(manifest.relative_to(ROOT)), origin="upstream", complexity=definition["complexity"]))
        if manifest.exists():
            existing = load_case(manifest)
            inventory[-1]["dataset"] = existing["dataset"]
            inventory[-1]["origin"] = existing["source"]["change_origin"]
            if existing["source"].get("upstream_commit"):
                inventory[-1]["upstream_change"] = existing["source"]["upstream_commit"]
            continue
        folder = manifest.parent / name
        folder.mkdir(parents=True, exist_ok=True)
        case = copy.deepcopy(template)
        case.update(id=name, group=name, types=[definition["type"]], dataset=definition["dataset"], corpus_status="pending_independent_review", expected_terminal="packaged")
        case["source"] = dict(url="https://github.com/usememos/memos.git", license=dict(spdx="MIT", path="LICENSE", sha256=sha(blob(commit, "LICENSE"))), base_commit=parent, reviewed_commit=commit, reviewed_tree=tree, change_origin="upstream", commit_url=f"https://github.com/usememos/memos/commit/{commit}")
        limits = list(definition["limits"])
        if definition.get("media"):
            limits.append("The required interface media remain absent until a separate capture and independent review.")
        limits.append("The reports are authored experiment fixtures. No Culler Worker, Verifier, or Scribe executed this task.")
        case["references"] = dict(review_status="pending", provenance="authored_from_pinned_source", facts=facts, limits=limits, review_requirements=["An independent reviewer must inspect the complete pinned change range.", "The reviewer must verify every material claim, condition, and evidence limit.", "The reviewer must inspect authored history and supplied media before acceptance."])
        version = 2 if definition.get("earlier_requirements") else 1
        criteria = [item["after"] for item in facts] + facts[0]["conditions"][:2]
        purpose = facts[0]["after"]
        description = purpose + "\n\nAcceptance criteria:\n" + "\n".join("- " + value for value in criteria)
        task = dict(id=number, title=definition["title"], purpose=purpose, acceptance_criteria=criteria, requirements_version=version, description=description)
        role = case["role_inputs"]
        role["task"] = task
        role["command_responses"] = {f"task get {number}": task | dict(status="packaging", project_id="memos-evaluation"), "task list": [task | dict(status="packaging", project_id="memos-evaluation")], "packet list": [], "project list": [dict(id="memos-evaluation", name="Memos", repo_path="/workspace/source")]}
        role["brief_parts"] = [
            dict(heading="Run", explanation="This value identifies this run. It is the `<run_id>` value of each `mc` command.", facts=[dict(label="Run identifier", value="{{run_id}}")]),
            dict(heading="Task", explanation="This is the subject of your review packet. The packet covers each criterion in the description.", facts=[dict(label="Identifier", value=str(number)), dict(label="Title", value=task["title"]), dict(label="Requirements version", value=str(version))], text_tag="description", text=description),
            dict(heading="Latest verdict", explanation="This is the most recent Verifier verdict on the current requirements of this work.", facts=[dict(label="Outcome", value="pass"), dict(label="Requirements version", value=str(version)), dict(label="Evidence file", value=f"/mc/artifacts/eval/{number}/verifier.txt")]),
            dict(heading="Verdict history", explanation="Each Verifier verdict on this work, oldest first. The revision history of the packet cites each one.", rows=[dict(requirements_version=version, current_requirements=True, outcome="pass", evidence_path=f"/mc/artifacts/eval/{number}/verifier.txt", correction_path="")]),
            dict(heading="Last completion report", explanation="The producer of this work wrote this report in its last run. It is a claim that you must check, not evidence.", facts=[dict(label="File", value=f"/mc/artifacts/eval/{number}/worker.txt"), dict(label="Requirements version", value=str(version))]),
            dict(heading="Git state", explanation="These are the Git facts of this work. The Files changed view shows the reviewed commits and complete diff.", facts=[dict(label=label, value=value) for label, value in [("Start commit", commit), ("Base commit", parent), ("Submitted commit", commit), ("Submitted version", str(version)), ("Verified source commit", commit), ("Scribe input commit", commit), ("Scribe result commit", commit), ("Scribe state", "complete")]])]
        diff_check = git("diff", "--check", parent, commit, check=False)
        observation = dict(method="git-source-range", base_commit=parent, reviewed_commit=commit, reviewed_tree=tree, changed_paths=changed, result="reconstructed")
        worker = dict(role="Worker", provenance="authored_for_experiment", scope="The case author inspected actual pinned source. No Culler Worker executed this task.", task_id=number, requirements_version=version, verified_source_commit=commit, summary=purpose, explanation=[dict(after=f["after"], mechanism=f["mechanism"], conditions=f["conditions"]) for f in facts], checks=[observation, dict(name="git diff --check", result="pass" if diff_check.returncode == 0 else "fail", output=diff_check.stdout.decode()+diff_check.stderr.decode(), exit_code=diff_check.returncode)], unverified=limits)
        verifier = dict(role="Verifier", provenance="authored_for_experiment", scope="The case author reconstructed the source range and inspected it. This record is not a captured Culler Verifier run.", task_id=number, requirements_version=version, outcome="pass", criteria=[dict(criterion=value, result="source_inspection", evidence=[dict(path=s["path"], revision=commit) for f in facts for s in f["sources"]]) for value in criteria], execution_evidence=dict(git_diff_check=dict(exit_code=diff_check.returncode, output=diff_check.stdout.decode()+diff_check.stderr.decode()), source_observation=observation), media=[], media_status="missing" if definition.get("media") else "not_applicable", unverified=limits)
        artifacts = []
        paths = {"/workspace/source": "repository"}
        for filename, artifact_id, report in [("worker.txt", "worker-report", worker), ("verifier.txt", "verifier-evidence", verifier)]:
            report_hash = write(folder / filename, report)
            destination = f"eval/{number}/{filename}"
            artifacts.append(dict(id=artifact_id, kind="report", visibility="role", path=destination, source=dict(kind="file", path=f"{name}/{filename}"), sha256=report_hash, provenance="authored_for_experiment"))
            paths["/mc/artifacts/"+destination] = artifact_id
        role["upstream_reports"] = [dict(artifact=a["id"], provenance=a["provenance"]) for a in artifacts]
        if definition.get("correction"):
            rejected = definition["rejected_claim"]
            old_version = 1 if definition.get("earlier_requirements") else version
            previous = dict(role="Verifier", provenance="authored_for_experiment", scope="This is an authored source-inspection history, not an executed Culler run.", task_id=number, requirements_version=old_version, outcome="fail", rejected_claim=rejected, finding="The claim contradicts the pinned source conditions.", evidence=[dict(path=s["path"], revision=commit) for f in facts for s in f["sources"]], unverified=limits)
            correction = dict(provenance="authored_for_experiment", task_id=number, requirements_version=version, rejected_claim=rejected, correction="Preserve the source conditions and evidence limits in the report and packet.", replacement_claim=purpose)
            for filename, artifact_id, report in [("earlier-verdict.txt", "earlier-verdict", previous), ("correction.txt", "correction", correction)]:
                report_hash = write(folder / filename, report)
                destination = f"eval/{number}/{filename}"
                artifacts.append(dict(id=artifact_id, kind="report", visibility="role", path=destination, source=dict(kind="file", path=f"{name}/{filename}"), sha256=report_hash, provenance="authored_for_experiment"))
                paths["/mc/artifacts/"+destination] = artifact_id
                role["upstream_reports"].append(dict(artifact=artifact_id, provenance="authored_for_experiment"))
            history = next(p for p in role["brief_parts"] if p["heading"] == "Verdict history")
            history["rows"].insert(0, dict(requirements_version=old_version, current_requirements=old_version == version, outcome="fail", evidence_path=f"/mc/artifacts/eval/{number}/earlier-verdict.txt", correction_path=f"/mc/artifacts/eval/{number}/correction.txt"))
            case["references"]["facts"].append(dict(id="authored-correction-history", before="The authored earlier report includes an overbroad source claim.", after="The authored correction rejects that claim; the latest source-inspection verdict passes the narrower claim.", mechanism="The fixture supplies both verdicts and the correction so the packet can show their order.", conditions=["The records describe source inspection, not application execution.", "Both verdicts use the actual reviewed source; this fixture records a report correction, not an extra implementation commit."], sources=facts[0]["sources"]))
        if definition.get("earlier_requirements"):
            role["brief_parts"].append(dict(heading="Earlier requirements", explanation="These are the earlier requirements of this work. The current requirements supersede this version.", facts=[dict(label="Requirements version", value="1")], text_tag="description", text="Use local storage for fresh instances. Version 2 also requires the upgrade path to preserve existing defaults."))
        if definition.get("scribe"):
            docs = [p for p in changed if p.endswith(".md") or p.endswith("doc.go")]
            scribe = dict(role="Scribe", provenance="authored_for_experiment", scope="The case author inspected the upstream documentation in the reviewed commit. No separate Scribe run or commit occurred.", source_commit=commit, result_commit=commit, changed_documentation=docs, evidence_scope="Documentation source inspection only.", unverified=limits)
            report_hash = write(folder / "scribe.txt", scribe)
            destination = f"eval/{number}/scribe.txt"
            artifacts.append(dict(id="scribe-report", kind="report", visibility="role", path=destination, source=dict(kind="file", path=f"{name}/scribe.txt"), sha256=report_hash, provenance="authored_for_experiment"))
            paths["/mc/artifacts/"+destination] = "scribe-report"
            role["upstream_reports"].append(dict(artifact="scribe-report", provenance="authored_for_experiment"))
            role["brief_parts"].append(dict(heading="Scribe report", explanation="This report describes the documentation source supplied with the change. It does not establish application behavior.", facts=[dict(label="File", value="/mc/artifacts/"+destination)], text_tag="description", text="The upstream reviewed commit contains the stated documentation changes. This fixture adds no separate Scribe source commit."))
        artifacts.append(dict(id="reviewed-diff", kind="source_diff", visibility="judge", path="reviewed.diff", source=dict(kind="git_diff"), sha256=sha(git("diff", "--binary", "--no-ext-diff", "--no-textconv", parent, commit).stdout), provenance="captured_git_command"))
        case["artifacts"], case["paths"] = artifacts, paths
        media = bool(definition.get("media"))
        case["visual_evidence"] = dict(required=media, status="missing" if media else "not_applicable", capture_instructions=definition.get("states", []))
        if not media:
            case["visual_evidence"]["reason"] = "The change adds no new rendered interface element or layout. Its source behavior and evidence limits define this case."
        locks = []
        for path in ["go.mod", "go.sum", "web/package.json", "web/pnpm-lock.yaml", "web/bun.lock", "web/bun.lockb"]:
            result = git("show", f"{commit}:{path}", check=False)
            if result.returncode == 0:
                locks.append(dict(path=path, sha256=sha(result.stdout)))
        case["environment"] = dict(trial=dict(source_access="read_only", application_build_required=False, application_instance_required=False, source_tools=["git"], platform="configured isolated harness container"), capture=dict(source_revisions=[parent, commit], method="The capture must render literal source components with fixed authoritative data.", states=definition["states"], status="pending") if media else None, dependency_locks=locks)
        case["content_hashes"] = {key:content_hash(case[key]) for key in ["role_inputs", "references", "project_skills", "environment", "visual_evidence"]}
        write(manifest, case)
        load_case(manifest)
        created += 1
    counts = {dataset:{kind:0 for kind in CASE_TYPES} for dataset in ["trainset", "valset", "final"]}
    for record in inventory:
        for kind in record["types"]:
            counts[record["dataset"]][kind] += 1
    expected = {dataset: {kind: 2 for kind in CASE_TYPES} for dataset in ("trainset", "valset")}
    expected["trainset"]["feature_across_components"] = 1
    expected["valset"]["performance_change"] = 1
    expected["final"] = {kind: 1 for kind in CASE_TYPES}
    for kind in ("feature_across_components", "performance_change"):
        expected["final"][kind] = 2
    assert len(inventory) == 35 and len({r["group"] for r in inventory}) == 35
    assert counts == expected
    status = "ready" if all(case_readiness(load_case(ROOT / record["manifest"]))["ready"] for record in inventory) else "pending_independent_review_and_media"
    write(ROOT / "corpus.json", dict(schema_version=1, source="https://github.com/usememos/memos.git", status=status, assignments=inventory, counts=counts, limits=["A dataset assignment does not establish case readiness.", "The five pilot groups remain in the trainset and outside the final set.", "No application test execution follows from an authored report."]))
    print(f"Corpus prepared: {len(inventory)} case assignments.")
    print(f"Created {created} cases; preserved {len(inventory)-created} cases.")
    print("Cases need independent source review and required media before live trials.")


if __name__ == "__main__":
    main()
